const textareaClass = 'w-full rounded-lg border bg-background px-3 py-2 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring';
const statusClass: Record<EventRegistrationStatus, string> = {
  confirmed: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300', pending: 'bg-amber-500/10 text-amber-700 dark:text-amber-300',
  waitlisted: 'bg-sky-500/10 text-sky-700 dark:text-sky-300', declined: 'bg-red-500/10 text-red-700 dark:text-red-300', cancelled: 'bg-muted text-muted-foreground',
};

function RegistrationForm({ contest, existing, onSaved, onCancelEdit,now,readOnly=false }: { now:number|null;contest: Contest; existing?: EventRegistration | null; onSaved: (entry: EventRegistration) => void; onCancelEdit?: () => void;readOnly?:boolean }) {
  const { user, profile } = useAuth();
  const reduced=useReducedMotion();
  const funnel=useProductFunnel<{identity:Record<string,never>;questions:Record<string,never>}>({id:`contest-registration-${contest.id}`,initial:{step:'identity',context:{}}});
  const hasQuestions=contest.registration_questions.length>0;

  const { showError, showSuccess } = useAlert();
  const [name, setName] = useState(existing?.attendee_name || profile?.full_name || '');
  const [answers, setAnswers] = useState<Record<string, RegistrationAnswer>>(existing?.answers || {});
  const registrationPhase=contestRegistrationPhase(contest,now);
  const activeExisting=existing&&!['cancelled','declined'].includes(existing.status);
  const [kind,setKind]=useState<'individual'|'team_create'|'team_join'>(contest.participation_mode==='team'?'team_create':'individual');
  const [teamName,setTeamName]=useState(''),[joinCode,setJoinCode]=useState('');
  useEffect(()=>{const code=new URL(window.location.href).searchParams.get('team');if(code&&contest.participation_mode==='team'){setKind('team_join');setJoinCode(code)}},[contest.participation_mode]);
  const [busy, setBusy] = useState(false);
  const update = (id: string, value: RegistrationAnswer) => setAnswers(prev => ({ ...prev, [id]: value }));
  async function submit(event: React.FormEvent) {
    event.preventDefault();
    if (readOnly || !user || busy || registrationPhase!=='open') return;
    if(hasQuestions&&funnel.step==='identity'){
      if(!name.trim())return showError('참가자 이름을 입력해 주세요.');
      if(!activeExisting&&kind==='team_create'&&!teamName.trim())return showError('팀 이름을 입력해 주세요.');
      if(!activeExisting&&kind==='team_join'&&!contestTeamJoinCode(joinCode))return showError('올바른 팀 초대 링크 또는 코드를 입력해 주세요.');
      await funnel.history.push('questions',{});return;
    }
    for (const question of contest.registration_questions) {
      const answer = answers[question.id];
      if (question.required && (answer === undefined || answer === '' || answer === false || (Array.isArray(answer) && !answer.length))) return showError(`${question.label} 항목에 답해 주세요.`);
    }
    setBusy(true);
    try {
      if(!activeExisting&&kind==='team_create'&&!teamName.trim())throw Error('팀 이름을 입력해 주세요.');
      const code=kind==='team_join'?contestTeamJoinCode(joinCode):null;
      if(!activeExisting&&kind==='team_join'&&!code)throw Error('올바른 팀 초대 링크 또는 코드를 입력해 주세요.');
      const {data,error}=activeExisting
       ?await supabase.from('event_registrations').update({attendee_name:name.trim(),answers}).eq('id',existing.id).select('*').single()
       :await supabase.rpc('register_contest_entry',{p_contest_id:contest.id,p_attendee_name:name.trim(),p_answers:answers,p_kind:contest.participation_mode==='team'?kind:'individual',p_team_name:kind==='team_create'?teamName.trim():null,p_join_code:code}).single();
      if (error) throw error;
      window.dispatchEvent(new Event('cbgpu:contest-registration'));
      onSaved(data); showSuccess(existing && !['cancelled','declined'].includes(existing.status) ? '참가 신청 정보를 수정했어요.' : data.status === 'confirmed' ? '참가가 확정되었어요!' : data.status === 'pending' ? '참가 신청을 보냈어요.' : '대기 명단에 등록되었어요.');
    } catch (error) { showError(eventError(error)); } finally { setBusy(false); }
  }
  return <form id="contest-registration" onSubmit={submit} className="contest-panel space-y-5"><fieldset disabled={readOnly||busy||registrationPhase!=='open'} className="space-y-5"><div><p className="contest-eyebrow mb-2 text-primary">REGISTRATION</p><h2 className="text-xl font-bold">참가 신청</h2></div>
    {hasQuestions&&<div className="contest-registration-progress" aria-label="신청 단계"><span aria-current={funnel.step==='identity'?'step':undefined}><b>01</b>참가 정보</span><i/><span aria-current={funnel.step==='questions'?'step':undefined}><b>02</b>신청서 작성</span></div>}
    <AnimatePresence mode="wait" initial={false}><motion.div key={funnel.step} initial={{opacity:0,x:reduced?0:12}} animate={{opacity:1,x:0}} exit={{opacity:0,x:reduced?0:-10}} transition={{duration:reduced?0:.18}} className="space-y-5" onAnimationComplete={()=>{if(funnel.step==='questions')document.querySelector<HTMLElement>('#contest-registration [data-registration-question] :is(textarea,input,select,button)')?.focus({preventScroll:true});}}>
    {funnel.step==='identity'&&<div className="space-y-5">
    {contest.participation_mode==='team'&&!activeExisting&&<fieldset className="space-y-3 rounded-2xl border p-4"><legend className="px-1 text-sm font-bold">팀 참가 방식 · {contest.team_min_size}–{contest.team_max_size}명</legend><div className="flex flex-wrap gap-3">{([['team_create','새 팀 만들기'],['team_join','초대받은 팀 합류'],...(contest.allow_individual_entries?[['individual','개인 신청 · 랜덤 배정']]:[])] as ['individual'|'team_create'|'team_join',string][]).map(([value,label])=><label key={value} className="flex min-h-10 items-center gap-2 text-sm"><input type="radio" name={`contest-team-entry-${contest.id}`} checked={kind===value} onChange={()=>setKind(value)}/>{label}</label>)}</div>{kind==='team_create'&&<label className="block space-y-2 text-sm font-semibold">팀 이름<Input required maxLength={80} value={teamName} onChange={e=>setTeamName(e.target.value)} placeholder="예: 과학하는 친구들"/></label>}{kind==='team_join'&&<label className="block space-y-2 text-sm font-semibold">팀 초대 링크 또는 코드<Input required value={joinCode} onChange={e=>setJoinCode(e.target.value)} placeholder="팀장이 공유한 링크를 붙여 넣으세요"/></label>}<p className="text-xs leading-relaxed text-muted-foreground">{kind==='individual'?'참가 확정 후 신청 마감 시점에 설정된 인원 범위에 맞춰 랜덤 팀에 배정돼요. 인원이 부족하면 배정 대기로 남아요.':'각 팀원이 CBGPU에 로그인하고 직접 신청해야 팀에 포함돼요. 팀 생성 후 내 참가 팀에서 초대 링크를 복사할 수 있어요.'}</p></fieldset>}
    <label className="block space-y-2 text-sm font-bold"><span>참가자 이름</span><Input required maxLength={100} value={name} onChange={e => setName(e.target.value)} /></label>
    </div>}
    {funnel.step==='questions'&&<div className="contest-registration-summary"><span>참가자</span><strong>{name}</strong><button type="button" onClick={()=>void funnel.history.back()}>수정</button></div>}
    {funnel.step==='questions'&&contest.registration_questions.map(question => <fieldset data-registration-question key={question.id} className="space-y-2"><legend className="mb-2 text-sm font-bold">{question.label}{question.required && <span className="ml-1 text-destructive">*</span>}</legend>
      {question.type === 'paragraph' ? <textarea className={textareaClass} rows={4} maxLength={2000} required={question.required} value={String(answers[question.id] || '')} onChange={e => update(question.id, e.target.value)} /> : question.type === 'choice' ? <div className="space-y-2">{question.options.map(option => <label key={option} className="flex items-center gap-2 text-sm"><input type="radio" name={question.id} required={question.required} checked={answers[question.id] === option} onChange={() => update(question.id, option)} />{option}</label>)}</div> : question.type === 'checkbox' ? <div className="space-y-2">{question.options.map(option => { const values = Array.isArray(answers[question.id]) ? answers[question.id] as string[] : []; return <label key={option} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={values.includes(option)} onChange={e => update(question.id, e.target.checked ? [...values, option] : values.filter(value => value !== option))} />{option}</label>; })}</div> : question.type === 'terms' ? <label className="flex items-start gap-2 rounded-lg bg-muted/50 p-3 text-sm"><input type="checkbox" required={question.required} checked={answers[question.id] === true} onChange={e => update(question.id, e.target.checked)} />{question.label}</label> : <Input required={question.required} maxLength={500} value={String(answers[question.id] || '')} onChange={e => update(question.id, e.target.value)} />}
    </fieldset>)}
    </motion.div></AnimatePresence>
    <div className="contest-registration-actions flex gap-2">{funnel.step==='questions'&&<Button type="button" variant="outline" onClick={()=>void funnel.history.back()}>이전</Button>}{onCancelEdit && <Button type="button" variant="outline" className="flex-1" onClick={onCancelEdit}>취소</Button>}<Button type="submit" size="lg" className="flex-1" disabled={busy || !name.trim() || registrationPhase!=='open'}><Send />{busy ? '저장 중…' : hasQuestions&&funnel.step==='identity'?'다음 · 신청서 작성':existing ? ['cancelled','declined'].includes(existing.status) ? '다시 신청하기' : '신청 정보 저장' : contest.approval_required ? '참가 승인 요청하기' : '참가 신청하기'}</Button></div>
  </fieldset></form>;
}

function GuestTicket({ contest, registration, access, onCancelled, onEdit,readOnly=false }: { contest: Contest; registration: EventRegistration; access: EventAccessDetails | null; onCancelled: () => void; onEdit: () => void;readOnly?:boolean }) {
  const { showError, showSuccess, confirm } = useAlert();
  const [busy, setBusy] = useState(false);
  const confirmed = registration.status === 'confirmed';
  return <motion.section initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} transition={{type:'spring',stiffness:260,damping:27}} className="contest-panel contest-ticket-panel space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="contest-eyebrow mb-2 text-primary">MY REGISTRATION</p><h2 className="text-xl font-bold">{registration.attendee_name}</h2></div><span className={`rounded-full px-3 py-1.5 text-xs font-bold ${statusClass[registration.status]}`}>{REGISTRATION_STATUS_LABELS[registration.status]}</span></div>
    {registration.status === 'pending' && <p className="text-sm text-muted-foreground">호스트가 신청 내용을 확인하고 있어요. 승인되면 QR 티켓과 온라인 접속 링크가 열립니다.</p>}
    {registration.status === 'waitlisted' && <p className="text-sm text-muted-foreground">정원이 차서 대기 명단에 등록됐어요. 자리가 생기면 호스트가 참가를 확정할 수 있어요.</p>}
    {confirmed && <div className="grid gap-5 sm:grid-cols-[180px_1fr] sm:items-center"><div className="mx-auto rounded-2xl border bg-white p-3"><QRCodeSVG value={`cbgpu:event:${contest.id}:${registration.ticket_code}`} size={150} level="M" /></div><div className="space-y-3"><h3 className="flex items-center gap-2 font-bold"><TicketCheck className="size-5 text-primary" />체크인 QR 티켓</h3><p className="text-sm text-muted-foreground">행사 입장 시 운영진에게 이 QR을 보여주세요.</p>{registration.checked_in_at && <p className="text-sm font-semibold text-emerald-600">{formatContestDate(registration.checked_in_at)} 체크인 완료</p>}</div></div>}
    {confirmed && access?.meeting_url && <a href={access.meeting_url} target="_blank" rel="noopener noreferrer" className="flex items-center justify-between rounded-2xl border bg-primary/5 p-4 text-sm font-bold text-primary">온라인 행사 입장하기<ExternalLink className="size-4" /></a>}
    {confirmed && access?.access_note && <p className="whitespace-pre-wrap rounded-lg bg-muted/50 p-4 text-sm">{access.access_note}</p>}
    <div className="flex flex-wrap gap-2"><Button type="button" variant="outline" disabled={readOnly} onClick={()=>{if(!readOnly)onEdit()}}>{['declined','cancelled'].includes(registration.status) ? '다시 신청' : '신청 정보 수정'}</Button>{!['declined', 'cancelled'].includes(registration.status) && <Button type="button" variant="ghost" disabled={readOnly||busy} onClick={async () => { if(readOnly)return;if (!await confirm({ title: '참가 신청을 취소할까요?', message: '취소하면 다시 신청해야 해요.', confirmLabel: '신청 취소', cancelLabel: '닫기' })) return; setBusy(true); try { const { error } = await supabase.from('event_registrations').update({ status: 'cancelled' }).eq('id', registration.id); if (error) throw error;window.dispatchEvent(new Event('cbgpu:contest-registration')); showSuccess('참가 신청을 취소했어요.'); onCancelled(); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }}><CircleX />신청 취소</Button>}</div>
  </motion.section>;
}

function exportGuests(contest: Contest, registrations: EventRegistration[]) {
  const questions = contest.registration_questions;
  const safe = (value: unknown) => { let text = Array.isArray(value) ? value.join(' | ') : String(value ?? ''); if (/^[=+\-@]/.test(text)) text = `'${text}`; return `"${text.replace(/"/g, '""')}"`; };
  const rows = [['이름', '상태', '신청 시각', '체크인 시각', ...questions.map(q => q.label)], ...registrations.map(registration => [registration.attendee_name, REGISTRATION_STATUS_LABELS[registration.status], formatContestDate(registration.created_at), registration.checked_in_at ? formatContestDate(registration.checked_in_at) : '', ...questions.map(q => registration.answers[q.id] ?? '')])];
  const blob = new Blob(['\ufeff' + rows.map(row => row.map(safe).join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${contest.title}_참가자.csv`; anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function QrScanner({ onCode }: { onCode: (value: string) => void }) {
  const videoRef = useRef<HTMLVideoElement>(null); const streamRef = useRef<MediaStream | null>(null); const timerRef = useRef<number | null>(null);
  const [active, setActive] = useState(false); const { showError } = useAlert();
  const stop = useCallback(() => { if (timerRef.current) window.clearInterval(timerRef.current); timerRef.current = null; streamRef.current?.getTracks().forEach(track => track.stop()); streamRef.current = null; setActive(false); }, []);
  useEffect(() => stop, [stop]);
  async function start() {
    const Detector = (window as unknown as { BarcodeDetector?: new (options: { formats: string[] }) => { detect: (source: HTMLVideoElement) => Promise<Array<{ rawValue: string }>> } }).BarcodeDetector;
    if (!Detector) return showError('이 브라우저는 카메라 QR 인식을 지원하지 않아요. Chrome에서 열거나 티켓 코드를 직접 입력해 주세요.');
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false }); streamRef.current = stream;
      if (!videoRef.current) return stop(); videoRef.current.srcObject = stream; await videoRef.current.play(); setActive(true);
      const detector = new Detector({ formats: ['qr_code'] });
      timerRef.current = window.setInterval(async () => { if (!videoRef.current) return; const codes = await detector.detect(videoRef.current).catch(() => []); if (codes[0]?.rawValue) { onCode(codes[0].rawValue); stop(); } }, 500);
    } catch { stop(); showError('카메라를 열 수 없어요. 브라우저의 카메라 권한을 확인해 주세요.'); }
  }
  return <div className="space-y-2">{active && <video ref={videoRef} muted playsInline className="aspect-video w-full rounded-2xl bg-black object-cover" />} {!active && <video ref={videoRef} muted playsInline className="hidden" />}<Button type="button" variant="outline" className="w-full" onClick={() => active ? stop() : void start()}><Camera />{active ? '스캔 중지' : '카메라로 QR 스캔'}</Button></div>;
}

function HostTeam({ contest }: { contest: Contest }) {
  const { showError, showSuccess } = useAlert();
  const [hosts, setHosts] = useState<EventHost[]>([]);
  const [profiles, setProfiles] = useState<Record<string, { full_name: string | null; student_id: string | null }>>({});
  const [studentId, setStudentId] = useState(''); const [role, setRole] = useState<'manager' | 'checkin'>('manager'); const [busy, setBusy] = useState(false);
  const load = useCallback(async () => {
    const { data, error } = await supabase.from('event_hosts').select('*').eq('contest_id', contest.id).order('created_at');
    if (error) return showError(eventError(error));
    const entries = (data || []) as EventHost[]; setHosts(entries);setProfiles({});
    if (entries.length) { const { data: people,error } = await contestOperatorProfiles(supabase,contest.id,entries.map(item => item.user_id)); if(error){setProfiles({});showError(eventError(error));return;} setProfiles(Object.fromEntries((people || []).map(person => [person.id, person]))); }
  }, [contest.id, showError]);
  useEffect(() => { void load(); }, [load]);
  async function addHost(event: React.FormEvent) {
    event.preventDefault(); setBusy(true);
    try {
      const { data: people, error } = await contestOperatorProfiles(supabase,contest.id,null,studentId.trim()); const person=people?.[0];
      if (error) throw error; if (!person) throw new Error('해당 학번의 사용자를 찾지 못했어요.'); if (person.id === contest.host_id) throw new Error('대회 생성자는 이미 최고 관리자예요.');
      const { error: insertError } = await supabase.from('event_hosts').upsert({ contest_id: contest.id, user_id: person.id, role }, { onConflict: 'contest_id,user_id' });
      if (insertError) throw insertError; setStudentId(''); await load(); showSuccess('공동 운영자를 추가했어요.');
    } catch (error) { showError(eventError(error)); } finally { setBusy(false); }
  }
  return <section id="contest-personal-operators" className="contest-panel space-y-4"><div><p className="contest-eyebrow mb-2 text-primary">TEAM</p><h2 className="flex items-center gap-2 text-lg font-bold"><Users className="size-5" />공동 운영자</h2></div><p className="text-xs text-muted-foreground">관리자는 참가자·일정·공지를 관리하고, 체크인 담당자는 출석만 처리할 수 있어요.</p><form onSubmit={addHost} className="flex flex-col gap-2 sm:flex-row"><Input required value={studentId} onChange={e => setStudentId(e.target.value)} placeholder={scopedProfilesEnabled()?"이 대회 학교의 학번으로 찾기":"학번으로 사용자 찾기"} /><Dropdown className={textareaClass} value={role} onChange={e => setRole(e.target.value as typeof role)}><option value="manager">관리자</option><option value="checkin">체크인 담당</option></Dropdown><Button type="submit" disabled={busy}><UserPlus />추가</Button></form>{hosts.map(host => <div key={host.user_id} className="flex flex-wrap items-center justify-between gap-3 rounded-2xl border p-3"><div><strong className="text-sm">{profiles[host.user_id]?.full_name || '사용자'}</strong><p className="text-xs text-muted-foreground">{profiles[host.user_id]?.student_id || host.user_id} · {host.role === 'manager' ? '관리자' : '체크인 담당'}</p></div><Button size="sm" variant="ghost" onClick={async () => { const { error } = await supabase.from('event_hosts').delete().eq('contest_id', contest.id).eq('user_id', host.user_id); if (error) showError(eventError(error)); else { await load(); showSuccess('공동 운영자를 제거했어요.'); } }}><CircleX />제거</Button></div>)}</section>;
}

function EventLifecycle({ contest, sessions, access, onUpdated }: { contest: Contest; sessions: EventSession[]; access: EventAccessDetails | null; onUpdated: (contest: Contest) => void }) {
  const { user } = useAuth(); const { showError, showSuccess, prompt } = useAlert(); const [busy, setBusy] = useState(false);
  async function setStatus(status: Contest['lifecycle_status']) {
    const message = status === 'cancelled' ? await prompt({ title: '행사를 취소할까요?', message: '참가자에게 보여줄 취소 사유를 입력해 주세요.', defaultValue: '호스트가 행사를 취소했어요.', confirmLabel: '행사 취소', cancelLabel: '닫기' }) : '';
    if (status === 'cancelled' && message === null) return;
    setBusy(true); try { const { data, error } = await supabase.from('contests').update({ lifecycle_status: status, cancellation_message: message || '' }).eq('id', contest.id).select('*').single(); if (error) throw error; onUpdated(data); showSuccess(status === 'published' ? '행사를 다시 공개했어요.' : status === 'cancelled' ? '행사를 취소 처리했어요.' : '행사를 보관했어요.'); } catch (error) { showError(eventError(error)); } finally { setBusy(false); }
  }
  async function duplicate() {
    if (!user) return; setBusy(true);
    try {
      const start = contest.event_start_at ? new Date(contest.event_start_at) : null; const duration = start && contest.event_end_at ? new Date(contest.event_end_at).getTime() - start.getTime() : 3600000;
      const nextStart = new Date(Math.max(Date.now() + 86400000, start?.getTime() || 0)); const nextEnd = new Date(nextStart.getTime() + duration);
      const { data, error } = await supabase.from('contests').insert({ host_id: user.id, title: `${contest.title} 복사본`, description: contest.description, fields: contest.fields, logo_path: contest.logo_path?.startsWith(user.id+'/') ? contest.logo_path : null, banner_path:contest.banner_path||null, event_start_at: nextStart.toISOString(), event_end_at: nextEnd.toISOString(), location_type: contest.location_type, location_name: contest.location_name, address: contest.address, visibility: 'unlisted', capacity: contest.capacity, waitlist_enabled: contest.waitlist_enabled, approval_required: contest.approval_required, registration_questions: contest.registration_questions,...contestDuplicatePolicy(contest,nextStart.getTime()-(start?.getTime()||nextStart.getTime()),multiSchoolEnabled),...contestTeamSettings(contest) }).select('id').single();
      if (error) throw error;
      if (access) { const { error: accessError } = await supabase.from('event_access_details').insert({ contest_id: data.id, meeting_url: access.meeting_url, access_note: access.access_note }); if (accessError) throw accessError; }
      if (sessions.length) { const offset = nextStart.getTime() - (start?.getTime() || nextStart.getTime()); const { error: sessionsError } = await supabase.from('event_sessions').insert(sessions.map(session => ({ contest_id: data.id, title: session.title, description: session.description, starts_at: new Date(new Date(session.starts_at).getTime() + offset).toISOString(), ends_at: new Date(new Date(session.ends_at).getTime() + offset).toISOString(), location: session.location, order_num: session.order_num }))); if (sessionsError) throw sessionsError; }
      showSuccess('행사를 복제했어요.'); window.location.assign(`/contests/${data.id}/manage`);
    } catch (error) { showError(eventError(error)); setBusy(false); }
  }
  return <section className="contest-panel space-y-4"><div><p className="contest-eyebrow mb-2 text-primary">LIFECYCLE</p><h2 className="text-lg font-bold">복제·취소·보관</h2></div><p className="text-sm text-muted-foreground">반복 행사는 설정과 세부 일정을 복제해 빠르게 만들 수 있어요. 게시 상태: {contest.lifecycle_status === 'published' ? '공개' : contest.lifecycle_status === 'cancelled' ? '취소' : '보관'}</p><div className="flex flex-wrap gap-2"><Button variant="outline" disabled={busy} onClick={() => void duplicate()}>행사 복제</Button>{contest.lifecycle_status === 'published' ? <Button variant="outline" disabled={busy} onClick={() => void setStatus('cancelled')}>행사 취소</Button> : <Button disabled={busy} onClick={() => void setStatus('published')}>행사 다시 공개</Button>}{contest.lifecycle_status !== 'archived' && <Button variant="ghost" disabled={busy} onClick={() => void setStatus('archived')}>목록에서 보관</Button>}</div></section>;
}

type ManagementSection='overview'|'guests'|'teams'|'schedule'|'updates'|'settings'|'operators'|'lifecycle';
function HostEventConsole({ contest, access, registrations, sessions, announcements, reload, onContestUpdated, isOwner, canManage,managementSection }: { contest: Contest; access: EventAccessDetails | null; registrations: EventRegistration[]; sessions: EventSession[]; announcements: EventAnnouncement[]; reload: () => Promise<void>; onContestUpdated: (contest: Contest) => void; isOwner: boolean; canManage: boolean;managementSection?:ManagementSection }) {
  const { user } = useAuth(); const { showError, showSuccess } = useAlert(); const [busy, setBusy] = useState(false);
  const [sessionTitle, setSessionTitle] = useState(''); const [sessionStart, setSessionStart] = useState(''); const [sessionEnd, setSessionEnd] = useState(''); const [sessionLocation, setSessionLocation] = useState('');
  const [noticeTitle, setNoticeTitle] = useState(''); const [noticeContent, setNoticeContent] = useState(''); const [audience, setAudience] = useState<'all' | 'confirmed' | 'pending' | 'waitlisted'>('all');
  const [ticket, setTicket] = useState('');
  const [localHostTab,setHostTab]=useState<ManagementSection>('overview');const hostTab=managementSection??localHostTab;
  const [guestQuery, setGuestQuery] = useState(''); const [selected, setSelected] = useState<string[]>([]);
  const [eventStart, setEventStart] = useState(() => contest.event_start_at ? new Date(new Date(contest.event_start_at).getTime() + 32400000).toISOString().slice(0, 19) : '');
  const [eventEnd, setEventEnd] = useState(() => contest.event_end_at ? new Date(new Date(contest.event_end_at).getTime() + 32400000).toISOString().slice(0, 19) : '');
  const [registrationOpens,setRegistrationOpens]=useState(()=>deadlineToInput(contest.registration_opens_at||null));
  const [registrationCloses, setRegistrationCloses] = useState(() => contest.registration_closes_at ? new Date(new Date(contest.registration_closes_at).getTime() + 32400000).toISOString().slice(0, 19) : '');
  const [capacity, setCapacity] = useState(contest.capacity ? String(contest.capacity) : ''); const [locationName, setLocationName] = useState(contest.location_name); const [address, setAddress] = useState(contest.address); const [meetingUrl, setMeetingUrl] = useState(access?.meeting_url || '');
  const stats = (status: EventRegistrationStatus) => registrations.filter(entry => entry.status === status).length;
  const filteredGuests = registrations.filter(entry => entry.attendee_name.toLowerCase().includes(guestQuery.trim().toLowerCase()) || REGISTRATION_STATUS_LABELS[entry.status].includes(guestQuery.trim()));
  async function updateRegistration(id: string, patch: Partial<Pick<EventRegistration, 'status' | 'checked_in_at'>>) { setBusy(true); try { if (patch.status) { const { data: sessionData } = await supabase.auth.getSession(); const response = await fetch(`/api/contests/${contest.id}/registrations`, { method: 'PATCH', headers: { 'content-type': 'application/json', authorization: `Bearer ${sessionData.session?.access_token || ''}` }, body: JSON.stringify({ ids: [id], status: patch.status }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error || '참가자 상태를 변경하지 못했어요.'); } else { const { error } = await supabase.from('event_registrations').update(patch).eq('id', id); if (error) throw error; } await reload(); showSuccess('참가자 상태를 변경하고 알림을 처리했어요.'); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }
  async function checkTicket() { const code = ticket.trim().split(':').at(-1); const entry = registrations.find(item => item.ticket_code === code && item.status === 'confirmed'); if (!entry) return showError('이 행사에서 사용할 수 있는 확정 티켓이 아니에요.'); await updateRegistration(entry.id, { checked_in_at: new Date().toISOString() }); setTicket(''); }
  async function bulkStatus(status: EventRegistrationStatus) { if (!selected.length) return; const count = selected.length; setBusy(true); try { const { data: sessionData } = await supabase.auth.getSession(); const response = await fetch(`/api/contests/${contest.id}/registrations`, { method: 'PATCH', headers: { 'content-type': 'application/json', authorization: `Bearer ${sessionData.session?.access_token || ''}` }, body: JSON.stringify({ ids: selected, status }) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error || '참가자 상태를 변경하지 못했어요.'); setSelected([]); await reload(); showSuccess(`${count}명의 상태와 이메일 알림을 처리했어요.`); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }
  if (!canManage) return <div className="space-y-6"><section className="contest-panel space-y-4"><div><p className="contest-eyebrow mb-2 text-primary">CHECK-IN MODE</p><h2 className="text-xl font-bold">현장 체크인</h2></div><div className="flex gap-2"><Input value={ticket} onChange={e => setTicket(e.target.value)} placeholder="QR 티켓 코드 직접 입력" onKeyDown={e => { if (e.key === 'Enter') void checkTicket(); }} /><Button type="button" disabled={!ticket.trim() || busy} onClick={() => void checkTicket()}><QrCode />체크인</Button></div><QrScanner onCode={value => { setTicket(value); const code = value.trim().split(':').at(-1); const entry = registrations.find(item => item.ticket_code === code && item.status === 'confirmed'); if (entry) void updateRegistration(entry.id, { checked_in_at: new Date().toISOString() }); else showError('이 행사에서 사용할 수 있는 확정 티켓이 아니에요.'); }} /><div className="space-y-2">{registrations.filter(entry => entry.status === 'confirmed').map(entry => <div key={entry.id} className="flex items-center justify-between gap-3 rounded-2xl border p-3"><div><strong className="text-sm">{entry.attendee_name}</strong><p className="text-xs text-muted-foreground">{entry.checked_in_at ? `${formatContestDate(entry.checked_in_at)} 체크인` : '미체크인'}</p></div><Button size="sm" variant="outline" disabled={busy} onClick={() => void updateRegistration(entry.id, { checked_in_at: entry.checked_in_at ? null : new Date().toISOString() })}>{entry.checked_in_at ? '취소' : '체크인'}</Button></div>)}</div></section></div>;
  return <div className="space-y-6">
    {!managementSection&&<nav className="contest-tabs max-w-full overflow-x-auto" aria-label="행사 운영 메뉴">{([['overview','현황'],['guests','참가자'],['schedule','일정'],['updates','공지'],['settings','설정']] as const).map(([key,label]) => <button key={key} type="button" aria-pressed={hostTab === key} onClick={() => setHostTab(key)}>{label}</button>)}</nav>}
    {hostTab === 'overview' && <><section className="grid grid-cols-2 gap-3 sm:grid-cols-4">{([['confirmed','확정'],['pending','승인 대기'],['waitlisted','대기'],['cancelled','취소']] as const).map(([key,label]) => <div key={key} className="rounded-2xl border bg-card p-4"><strong className="text-2xl">{stats(key)}</strong><p className="mt-1 text-xs text-muted-foreground">{label}</p></div>)}</section>
    <section className="contest-panel space-y-3"><div className="flex items-center justify-between text-sm"><strong>현장 체크인</strong><span>{registrations.filter(entry => entry.checked_in_at).length} / {stats('confirmed')}명</span></div><div className="h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-[width]" style={{ width: `${stats('confirmed') ? Math.round(registrations.filter(entry => entry.checked_in_at).length / stats('confirmed') * 100) : 0}%` }} /></div><div className="flex justify-between text-xs text-muted-foreground"><span>전체 신청 {registrations.filter(entry => !['cancelled','declined'].includes(entry.status)).length}명</span><span>체크인율 {stats('confirmed') ? Math.round(registrations.filter(entry => entry.checked_in_at).length / stats('confirmed') * 100) : 0}%</span></div></section></>}
    {hostTab === 'guests' && <section className="contest-panel space-y-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="contest-eyebrow mb-2 text-primary">GUESTS</p><h2 className="text-lg font-bold">참가자 관리</h2></div><div className="flex gap-2"><Button variant="outline" onClick={() => exportGuests(contest, registrations)}><Download />CSV</Button><Button variant="ghost" onClick={() => void reload()}><RefreshCw /></Button></div></div>
      <div className="flex gap-2"><Input value={ticket} onChange={e => setTicket(e.target.value)} placeholder="QR 티켓 코드 직접 입력" onKeyDown={e => { if (e.key === 'Enter') void checkTicket(); }} /><Button type="button" disabled={!ticket.trim() || busy} onClick={() => void checkTicket()}><QrCode />체크인</Button></div>
      <QrScanner onCode={value => { setTicket(value); const code = value.trim().split(':').at(-1); const entry = registrations.find(item => item.ticket_code === code && item.status === 'confirmed'); if (entry) void updateRegistration(entry.id, { checked_in_at: new Date().toISOString() }); else showError('이 행사에서 사용할 수 있는 확정 티켓이 아니에요.'); }} />
      {!!registrations.length && <><div className="relative"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input className="pl-9" value={guestQuery} onChange={e => setGuestQuery(e.target.value)} placeholder="이름 또는 상태 검색" /></div>{canManage && <div className="flex flex-wrap items-center gap-2"><Button size="sm" variant="outline" onClick={() => setSelected(selected.length === filteredGuests.length ? [] : filteredGuests.map(entry => entry.id))}>{selected.length === filteredGuests.length ? '전체 해제' : '전체 선택'}</Button>{selected.length > 0 && <><span className="text-xs text-muted-foreground">{selected.length}명 선택</span><Button size="sm" onClick={() => void bulkStatus('confirmed')}>일괄 승인</Button><Button size="sm" variant="outline" onClick={() => void bulkStatus('waitlisted')}>일괄 대기</Button><Button size="sm" variant="ghost" onClick={() => void bulkStatus('declined')}>일괄 거절</Button></>}</div>}</>}
      {!registrations.length ? <p className="rounded-2xl border border-dashed p-8 text-center text-sm text-muted-foreground">아직 참가 신청이 없어요.</p> : !filteredGuests.length ? <p className="rounded-2xl border border-dashed p-8 text-center text-sm text-muted-foreground">검색 결과가 없어요.</p> : <div className="space-y-2">{filteredGuests.map(entry => <details key={entry.id} className="rounded-2xl border p-4"><summary className="cursor-pointer list-none"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-3"><input type="checkbox" aria-label={`${entry.attendee_name} 선택`} checked={selected.includes(entry.id)} onClick={event => event.stopPropagation()} onChange={e => setSelected(prev => e.target.checked ? [...new Set([...prev, entry.id])] : prev.filter(id => id !== entry.id))} /><div><strong>{entry.attendee_name}</strong><p className="mt-1 text-xs text-muted-foreground">{formatContestDate(entry.created_at)}{entry.checked_in_at && ' · 체크인 완료'}</p></div></div><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${statusClass[entry.status]}`}>{REGISTRATION_STATUS_LABELS[entry.status]}</span></div></summary><div className="mt-4 space-y-4 border-t pt-4">{contest.registration_questions.map(q => <div key={q.id}><p className="text-xs font-bold text-muted-foreground">{q.label}</p><p className="mt-1 whitespace-pre-wrap text-sm">{Array.isArray(entry.answers[q.id]) ? (entry.answers[q.id] as string[]).join(', ') : String(entry.answers[q.id] ?? '-')}</p></div>)}<div className="flex flex-wrap gap-2">{entry.status !== 'confirmed' && <Button size="sm" disabled={busy} onClick={() => void updateRegistration(entry.id, { status: 'confirmed' })}><Check />승인</Button>}{entry.status !== 'waitlisted' && <Button size="sm" variant="outline" disabled={busy} onClick={() => void updateRegistration(entry.id, { status: 'waitlisted' })}><Clock3 />대기</Button>}{entry.status !== 'declined' && <Button size="sm" variant="ghost" disabled={busy} onClick={() => void updateRegistration(entry.id, { status: 'declined' })}><CircleX />거절</Button>}{entry.status === 'confirmed' && <Button size="sm" variant="outline" disabled={busy} onClick={() => void updateRegistration(entry.id, { checked_in_at: entry.checked_in_at ? null : new Date().toISOString() })}><TicketCheck />{entry.checked_in_at ? '체크인 취소' : '체크인'}</Button>}</div></div></details>)}</div>}
      {canManage && <Button type="button" variant="outline" className="w-full" disabled={busy} onClick={async () => { setBusy(true); try { const { data, error } = await supabase.from('contests').update({ registration_open: !contest.registration_open }).eq('id', contest.id).select('*').single(); if (error) throw error; onContestUpdated(data); showSuccess(data.registration_open ? '참가 신청을 열었어요.' : '참가 신청을 마감했어요.'); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }}>{contest.registration_open ? '참가 신청 마감하기' : '참가 신청 다시 열기'}</Button>}
    </section>}
    {hostTab === 'settings' && <><ContestTeamSettingsEditor contest={contest} onUpdated={onContestUpdated}/><section className="contest-panel space-y-4"><div><p className="contest-eyebrow mb-2 text-primary">SETTINGS</p><h2 className="flex items-center gap-2 text-lg font-bold"><Settings2 className="size-5" />행사 설정</h2></div><form className="grid gap-3 sm:grid-cols-2" onSubmit={async e => { e.preventDefault();const validation=contestPeriodError(deadlineToISO(registrationOpens),deadlineToISO(registrationCloses)||deadlineToISO(eventStart),'참가 신청');if(validation)return showError(validation);if(registrationCloses&&eventStart&&new Date(deadlineToISO(registrationCloses)!).getTime()>new Date(deadlineToISO(eventStart)!).getTime())return showError('참가 신청 마감은 행사 시작 이전으로 지정해 주세요.'); setBusy(true); try { const { data, error } = await supabase.from('contests').update({ registration_opens_at:deadlineToISO(registrationOpens),event_start_at: deadlineToISO(eventStart), event_end_at: deadlineToISO(eventEnd), registration_closes_at: deadlineToISO(registrationCloses), capacity: capacity ? Number(capacity) : null, location_name: locationName.trim(), address: address.trim() }).eq('id', contest.id).select('*').single(); if (error) throw error; const { error: accessError } = await supabase.from('event_access_details').upsert({ contest_id: contest.id, meeting_url: meetingUrl.trim() || null }, { onConflict: 'contest_id' }); if (accessError) throw accessError; onContestUpdated(data); await reload(); showSuccess('행사 설정을 저장했어요.'); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }}><label className="space-y-2 text-sm font-bold"><span>행사 시작</span><Input required type="datetime-local" step="1" value={eventStart} onChange={e => setEventStart(e.target.value)} /></label><label className="space-y-2 text-sm font-bold"><span>행사 종료</span><Input type="datetime-local" step="1" value={eventEnd} onChange={e => setEventEnd(e.target.value)} /></label><label className="space-y-2 text-sm font-bold"><span>신청 시작 (선택, 한국 시간)</span><Input type="datetime-local" step="1" value={registrationOpens} onChange={e=>setRegistrationOpens(e.target.value)}/></label><label className="space-y-2 text-sm font-bold"><span>신청 마감</span><Input type="datetime-local" step="1" value={registrationCloses} onChange={e => setRegistrationCloses(e.target.value)} /></label><label className="space-y-2 text-sm font-bold"><span>정원</span><Input type="number" min="1" max="10000" value={capacity} onChange={e => setCapacity(e.target.value)} placeholder="제한 없음" /></label><label className="space-y-2 text-sm font-bold"><span>장소 이름</span><Input value={locationName} maxLength={200} onChange={e => setLocationName(e.target.value)} /></label><label className="space-y-2 text-sm font-bold"><span>상세 위치</span><Input value={address} maxLength={500} onChange={e => setAddress(e.target.value)} /></label><label className="space-y-2 text-sm font-bold sm:col-span-2"><span>온라인 접속 링크</span><Input type="url" value={meetingUrl} onChange={e => setMeetingUrl(e.target.value)} placeholder="https://" /></label><Button type="submit" disabled={busy} className="sm:col-span-2">설정 저장</Button></form></section></>}
    {(hostTab==='operators'||!managementSection&&hostTab==='settings')&&<>{isOwner && multiSchoolEnabled && <ContestOrganizerSchools contestId={contest.id} schoolId={contest.school_id}/>}{isOwner && multiSchoolEnabled && <ContestOperatorReview contestId={contest.id}/>}{!isOwner && multiSchoolEnabled && <ContestOperatorSelf contestId={contest.id}/>} {isOwner && <HostTeam contest={contest} />}</>}
    {(hostTab==='lifecycle'||!managementSection&&hostTab==='settings')&&<>{isOwner && <EventLifecycle contest={contest} sessions={sessions} access={access} onUpdated={onContestUpdated} />}</>}
    {hostTab==='teams'&&<ContestTeamRoster contest={contest} host/>}
    {hostTab === 'schedule' && <section className="contest-panel space-y-4"><div><p className="contest-eyebrow mb-2 text-primary">SCHEDULE</p><h2 className="text-lg font-bold">세부 일정</h2></div>{sessions.map(session => <div key={session.id} className="flex items-start justify-between gap-3 rounded-2xl border p-3"><div><strong className="text-sm">{session.title}</strong><p className="mt-1 text-xs text-muted-foreground">{formatContestDate(session.starts_at)} – {formatContestDate(session.ends_at)}{session.location && ` · ${session.location}`}</p></div><Button size="icon" variant="ghost" onClick={async () => { await supabase.from('event_sessions').delete().eq('id', session.id); await reload(); }}><CircleX /></Button></div>)}<form className="grid gap-3 sm:grid-cols-2" onSubmit={async e => { e.preventDefault(); setBusy(true); try { const { error } = await supabase.from('event_sessions').insert({ contest_id: contest.id, title: sessionTitle.trim(), starts_at: deadlineToISO(sessionStart), ends_at: deadlineToISO(sessionEnd), location: sessionLocation.trim(), order_num: sessions.length }); if (error) throw error; setSessionTitle(''); setSessionStart(''); setSessionEnd(''); setSessionLocation(''); await reload(); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }}><Input required value={sessionTitle} onChange={e => setSessionTitle(e.target.value)} placeholder="세션 이름" /><Input value={sessionLocation} onChange={e => setSessionLocation(e.target.value)} placeholder="장소" /><Input required type="datetime-local" step="1" value={sessionStart} onChange={e => setSessionStart(e.target.value)} /><Input required type="datetime-local" step="1" value={sessionEnd} onChange={e => setSessionEnd(e.target.value)} /><Button type="submit" variant="outline" disabled={busy} className="sm:col-span-2">일정 추가</Button></form></section>}
    {hostTab === 'updates' && <section className="contest-panel space-y-4"><div><p className="contest-eyebrow mb-2 text-primary">UPDATES</p><h2 className="text-lg font-bold">공지·이메일 발송</h2></div>{announcements.slice(0, 3).map(notice => <div key={notice.id} className="rounded-2xl border p-3"><strong className="text-sm">{notice.title}</strong><p className="mt-1 whitespace-pre-wrap text-sm text-muted-foreground">{notice.content}</p></div>)}<form className="space-y-3" onSubmit={async e => { e.preventDefault(); if (!user) return; setBusy(true); try { const { data: sessionData } = await supabase.auth.getSession(); const response = await fetch(`/api/contests/${contest.id}/announce`, { method: 'POST', headers: { 'content-type': 'application/json', authorization: `Bearer ${sessionData.session?.access_token || ''}` }, body: JSON.stringify({ title: noticeTitle.trim(), content: noticeContent.trim(), audience }) }); const result = await response.json() as { error?: string; warning?: string; emailed?: number }; if (!response.ok) throw new Error(result.error || '공지를 보내지 못했어요.'); setNoticeTitle(''); setNoticeContent(''); await reload(); showSuccess(result.warning || `공지를 게시하고 ${result.emailed || 0}명에게 이메일을 보냈어요.`); } catch (error) { showError(eventError(error)); } finally { setBusy(false); } }}><Input required maxLength={150} value={noticeTitle} onChange={e => setNoticeTitle(e.target.value)} placeholder="공지 제목" /><textarea required maxLength={10000} rows={4} className={textareaClass} value={noticeContent} onChange={e => setNoticeContent(e.target.value)} placeholder="참가자에게 알릴 내용" /><Dropdown className={textareaClass} value={audience} onChange={e => setAudience(e.target.value as typeof audience)}><option value="all">모든 참가자</option><option value="confirmed">참가 확정자</option><option value="pending">승인 대기자</option><option value="waitlisted">대기 명단</option></Dropdown><Button type="submit" disabled={busy}><Megaphone />사이트 공지와 이메일 보내기</Button></form></section>}
  </div>;
}

export default function EventHub({ contest, isHost, isOwner, canManage, onContestUpdated,now,view,managementSection }: {view?:'participant'|'management'|'preview';managementSection?:ManagementSection; now:number|null;contest: Contest; isHost: boolean; isOwner: boolean; canManage: boolean; onContestUpdated: (contest: Contest) => void }) {
  const { user } = useAuth(); const { showError } = useAlert();
  const [registrations, setRegistrations] = useState<EventRegistration[]>([]); const [sessions, setSessions] = useState<EventSession[]>([]); const [announcements, setAnnouncements] = useState<EventAnnouncement[]>([]); const [access, setAccess] = useState<EventAccessDetails | null>(null); const [loading, setLoading] = useState(true);
  const [editingRegistration, setEditingRegistration] = useState(false);
  const load = useCallback(async () => { if(!user){setLoading(false);return;}if(!contest.event_start_at&&view!=='management'){setLoading(false);return;} try { const [r, s, a, d] = await Promise.all([supabase.from('event_registrations').select('*').eq('contest_id', contest.id).order('created_at'), supabase.from('event_sessions').select('*').eq('contest_id', contest.id).order('order_num'), supabase.from('event_announcements').select('*').eq('contest_id', contest.id).order('published_at', { ascending: false }), supabase.from('event_access_details').select('*').eq('contest_id', contest.id).maybeSingle()]); if (r.error) throw r.error; if (s.error) throw s.error; if (a.error) throw a.error; setRegistrations(r.data || []); setSessions(s.data || []); setAnnouncements(a.data || []); setAccess(d.data || null); } catch (error) { showError(eventError(error)); } finally { setLoading(false); } }, [contest.id, contest.event_start_at, showError, user,view]);
  useEffect(() => { void load();const timer=setInterval(()=>{if(document.visibilityState==='visible')void load()},15_000);return()=>clearInterval(timer); }, [load]);
  const preview=view==='preview',participant=preview||view==='participant',hostView=isHost&&!participant;
  if(view==='management')return isHost&&!loading?<HostEventConsole contest={contest} access={access} registrations={registrations} sessions={sessions} announcements={announcements} reload={load} onContestUpdated={onContestUpdated} isOwner={isOwner} canManage={canManage} managementSection={managementSection}/>:null;
  if (!contest.event_start_at) return null;
  const registrationPhase=contestRegistrationPhase(contest,now);
  const own = registrations.find(entry => entry.user_id === user?.id) || null;
  return <div className="space-y-6"><section className="contest-panel space-y-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="contest-eyebrow mb-2 text-primary">EVENT DETAILS</p><h2 className="text-xl font-bold">행사 안내</h2></div><Button variant="outline" onClick={() => downloadEventCalendar(contest)}><CalendarPlus />캘린더 추가</Button></div><div className="grid gap-3 text-sm sm:grid-cols-2"><p className="flex items-start gap-2"><Clock3 className="mt-0.5 size-4 text-primary" /><span>{formatContestDate(contest.event_start_at)}{contest.event_end_at && <><br />~ {formatContestDate(contest.event_end_at)}</>}</span></p><p className="flex items-start gap-2"><MapPin className="mt-0.5 size-4 text-primary" /><span>{contest.location_name || (contest.location_type === 'online' ? '온라인 행사' : '장소 추후 안내')}<br />{contest.address}</span></p></div>{contest.capacity && <p className="flex items-center gap-2 text-xs text-muted-foreground"><Users className="size-4" />정원 {contest.capacity}명{hostView && ` · 현재 확정 ${registrations.filter(r => r.status === 'confirmed').length}명`}</p>}</section>
    {contest.lifecycle_status === 'cancelled' && <section role="alert" className="rounded-2xl border border-red-500/20 bg-red-500/5 p-5"><h2 className="font-bold text-red-700 dark:text-red-300">취소된 행사예요</h2><p className="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{contest.cancellation_message}</p></section>}
    <section className="rounded-2xl border bg-card p-4 space-y-2"><h3 className="text-sm font-bold">참가 신청 기간</h3><p className="text-xs text-muted-foreground">{contest.registration_opens_at?formatContestDate(contest.registration_opens_at):'지금 신청 가능'} ~ {formatContestDate(contest.registration_closes_at||contest.event_start_at)}</p><p role="status" className="text-sm font-semibold">{registrationPhase==='pending'?`신청 시작 전 · ${remainingTime(contest.registration_opens_at!,now!)}`:registrationPhase==='checking'?'서버 시각을 확인하고 있어요…':registrationPhase==='closed'?'참가 신청이 마감되었어요.':'참가 신청을 받고 있어요.'}</p></section>
    {!hostView && !loading && (own && !editingRegistration ? <GuestTicket readOnly={preview} contest={contest} registration={own} access={access} onCancelled={() => void load()} onEdit={() => setEditingRegistration(true)} /> : contest.lifecycle_status === 'published' && contest.registration_open ? <RegistrationForm readOnly={preview} now={now} contest={contest} existing={own} onSaved={entry => { setRegistrations([entry]); setEditingRegistration(false);void load(); }} onCancelEdit={own ? () => setEditingRegistration(false) : undefined} /> : <div className="rounded-2xl border p-6 text-center text-sm text-muted-foreground">참가 신청이 마감되었어요.</div>)}
    <ContestTeamRoster contest={contest} host={hostView} readOnly={preview} registration={own}/>
    {!hostView && sessions.length > 0 && <section className="contest-panel space-y-4"><h2 className="text-lg font-bold">세부 일정</h2>{sessions.map(session => <div key={session.id} className="border-l-2 border-primary pl-4"><strong className="text-sm">{session.title}</strong><p className="mt-1 text-xs text-muted-foreground">{formatContestDate(session.starts_at)} · {session.location}</p>{session.description && <p className="mt-2 text-sm">{session.description}</p>}</div>)}</section>}
    {!hostView && announcements.length > 0 && <section className="contest-panel space-y-4"><h2 className="flex items-center gap-2 text-lg font-bold"><Megaphone className="size-5" />공지</h2>{announcements.map(notice => <article key={notice.id} className="rounded-2xl border p-4"><strong>{notice.title}</strong><p className="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{notice.content}</p><p className="mt-3 text-xs text-muted-foreground">{formatContestDate(notice.published_at)}</p></article>)}</section>}
    {hostView && !loading && <HostEventConsole contest={contest} access={access} registrations={registrations} sessions={sessions} announcements={announcements} reload={load} onContestUpdated={onContestUpdated} isOwner={isOwner} canManage={canManage} />}
  </div>;
}
